package service

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"strconv"
	"strings"
	"testing"

	"github.com/multica-ai/multica/server/internal/util"
	db "github.com/multica-ai/multica/server/pkg/db/generated"
	"github.com/multica-ai/multica/server/pkg/protocol"
)

const knowledgeC3Result = "C3 accepted reusable project convention"
const knowledgeC3Basis = "The exact accepted delivery supports the same convention"

type knowledgeC3ReplayFixture struct {
	source           *collaborationQueueFixture
	consumer         *taskKnowledgeFixture
	candidate        db.CollaborationKnowledgeCandidate
	acceptedSource   protocol.CollaborationKnowledgeSource
	descriptor       *protocol.TaskKnowledgeClaimDescriptor
	prepareRequest   protocol.TaskKnowledgePrepareRequest
	prepared         protocol.TaskKnowledgePrepareResponse
	authorizeRequest protocol.TaskKnowledgeAuthorizeRequest
	authorized       protocol.TaskKnowledgeAuthorization
	prepareHash      string
	authorizeHash    string
	originalTask     db.AgentTaskQueue
}

func knowledgeC3Log(t *testing.T, stage string, details map[string]any) {
	t.Helper()
	details["stage"] = stage
	details["test"] = t.Name()
	raw, err := json.Marshal(details)
	if err != nil {
		t.Fatal(err)
	}
	t.Log("C3_EVIDENCE " + string(raw))
}

func knowledgeC3Hash(t *testing.T, value any) string {
	t.Helper()
	hash, err := protocol.TaskKnowledgeRequestHash(value)
	if err != nil {
		t.Fatal(err)
	}
	return hash
}

func newKnowledgeC3ReplayFixture(t *testing.T, authorize bool) *knowledgeC3ReplayFixture {
	t.Helper()
	expectedDatabase := os.Getenv("MULTICA_KNOWLEDGE_MATRIX_DATABASE")
	if strings.TrimSpace(os.Getenv("DATABASE_URL")) == "" || !strings.HasPrefix(expectedDatabase, "mca_knowledge_c3_") {
		t.Fatal("C3 requires its explicit unique owned database; no skip or fallback")
	}
	source, accepted := knowledgeAcceptedSourceFixture(t, knowledgeC3Result, knowledgeC3Basis)
	var actualDatabase string
	if err := source.pool.QueryRow(source.ctx, "SELECT current_database()").Scan(&actualDatabase); err != nil || actualDatabase != expectedDatabase {
		t.Fatal("C3 database identity did not match its private allocation")
	}
	candidate := publishConsumptionProof(t, source, accepted, nil, 0, nil)
	consumer := automaticConsumerTask(t, source, candidate.TargetProjectID)
	descriptor := consumer.finalize(t, "")
	fixture := &knowledgeC3ReplayFixture{source: source, consumer: consumer, candidate: candidate, acceptedSource: accepted, descriptor: descriptor}
	fixture.prepareRequest = consumer.prepareRequest(descriptor)
	fixture.prepareHash = knowledgeC3Hash(t, fixture.prepareRequest)
	prepared, err := consumer.tasks.PrepareTaskKnowledge(consumer.ctx, consumer.caller, consumer.task.ID, fixture.prepareRequest)
	if err != nil || prepared.ProtocolVersion != 2 || len(prepared.Manifest.Entries) != 1 || len(prepared.Contributions) != 1 {
		t.Fatalf("original proof1 prepare admission failed: %v", err)
	}
	entry := prepared.Manifest.Entries[0]
	if entry.CandidateID != util.UUIDToString(candidate.ID) || entry.Version != strconv.FormatInt(candidate.Version, 10) || entry.ContentSHA256 != candidate.ContentSha256 || entry.Validity == nil || entry.Validity.Revision != "1" || entry.Validity.AcceptedEventSeq != accepted.AcceptedEventSeq || entry.Validity.SubmissionID != accepted.SubmissionID || prepared.ManifestSHA256 != knowledgeC3Hash(t, prepared.Manifest) || prepared.Contributions[0].Sources[0] != accepted {
		t.Fatal("original preparation did not bind the exact automatic proof1")
	}
	fixture.prepared = prepared
	replayed, err := consumer.tasks.PrepareTaskKnowledge(consumer.ctx, consumer.caller, consumer.task.ID, fixture.prepareRequest)
	if err != nil || !reflect.DeepEqual(replayed, prepared) {
		t.Fatalf("unchanged proof1 original prepare replay must succeed with its exact response: %v", err)
	}
	if authorize {
		fixture.authorizeRequest = consumer.authorizeRequest(prepared, descriptor)
		fixture.authorizeHash = knowledgeC3Hash(t, fixture.authorizeRequest)
		fixture.authorized, err = consumer.tasks.AuthorizeTaskKnowledgeLaunch(consumer.ctx, consumer.caller, consumer.task.ID, fixture.authorizeRequest)
		if err != nil {
			t.Fatalf("original proof1 authorize admission failed: %v", err)
		}
		replayedAuthorization, err := consumer.tasks.AuthorizeTaskKnowledgeLaunch(consumer.ctx, consumer.caller, consumer.task.ID, fixture.authorizeRequest)
		if err != nil || replayedAuthorization != fixture.authorized {
			t.Fatalf("unchanged proof1 original authorize replay must return the original receipt: %v", err)
		}
	}
	fixture.originalTask, err = consumer.tasks.Queries.GetAgentTask(consumer.ctx, consumer.task.ID)
	if err != nil {
		t.Fatal(err)
	}
	delivery, err := decodeTaskKnowledge(fixture.originalTask.KnowledgeContextVersion, fixture.originalTask.KnowledgeDelivery)
	if err != nil {
		t.Fatal(err)
	}
	claim, err := taskKnowledgeClaimAt(delivery, fixture.originalTask.ClaimGeneration)
	if err != nil || claim.Prepared == nil || claim.Prepared.RequestID != fixture.prepareRequest.RequestID || claim.Prepared.RequestHash != fixture.prepareHash || claim.Prepared.ID != prepared.PrepareID || claim.Prepared.ManifestSHA256 != prepared.ManifestSHA256 || !sameTaskKnowledgeManifest(claim.Prepared.Manifest, prepared.Manifest) {
		t.Fatal("the original prepare request/hash/manifest were not actually retained")
	}
	expectedAttempts := 0
	if authorize {
		expectedAttempts = 1
	}
	if len(claim.Attempts) != expectedAttempts {
		t.Fatal("original fixture has an unexpected physical-attempt inventory")
	}
	if authorize && (claim.Attempts[0].RequestID != fixture.authorizeRequest.RequestID || claim.Attempts[0].RequestHash != fixture.authorizeHash || claim.Attempts[0].Authorization != fixture.authorized || claim.Attempts[0].Refused || claim.Attempts[0].Terminated) {
		t.Fatal("the original authorize request/hash/receipt were not retained as admitted")
	}
	knowledgeC3Log(t, "original_admission_and_identical_replay", map[string]any{
		"database": actualDatabase, "task_id": util.UUIDToString(fixture.originalTask.ID), "prepare_request": fixture.prepareRequest,
		"prepare_request_sha256": fixture.prepareHash, "prepare_response": prepared, "authorize_request": fixture.authorizeRequest,
		"authorize_request_sha256": fixture.authorizeHash, "authorization_receipt": fixture.authorized,
		"retained_delivery_sha256": protocol.CollaborationKnowledgeHash(string(fixture.originalTask.KnowledgeDelivery)), "retained_attempt_count": expectedAttempts,
		"prepare_identical_replay_succeeded": true, "authorize_identical_replay_succeeded": authorize,
	})
	return fixture
}

func (fixture *knowledgeC3ReplayFixture) replaceProofThroughReacceptance(t *testing.T) KnowledgeResolution {
	t.Helper()
	source := fixture.source
	access := mustAccess(t, source, source.ctx)
	if _, err := source.svc.ChangeLifecycle(source.ctx, lifecycleParams(t, source, "reopen", "todo", access.Revision, access.LifecycleEpoch)); err != nil {
		t.Fatal("real source reopen failed:", err)
	}
	access = mustAccess(t, source, source.ctx)
	accept := lifecycleParams(t, source, "complete", "done", access.Revision, access.LifecycleEpoch)
	accept.Note, accept.Basis = knowledgeC3Result, knowledgeC3Basis
	if _, err := source.svc.ChangeLifecycle(source.ctx, accept); err != nil {
		t.Fatal("real formal reacceptance failed:", err)
	}
	summary := deliverySummaryForTest(t, source, source.ctx)
	issue, err := source.svc.Queries.GetIssue(source.ctx, fixture.candidate.SourceIssueID)
	if err != nil || summary.Latest == nil || summary.Latest.Decision == nil || summary.Latest.Decision.Kind != "accepted" {
		t.Fatal("reacceptance did not retain its exact accepted delivery:", err)
	}
	accepted, available, err := knowledgeAcceptedDelivery(source.ctx, source.svc.Queries, issue, summary.Latest.ID, summary.Latest.EventSeq, summary.Latest.Decision.EventSeq)
	if err != nil || !available || accepted.Source.SubmissionID == fixture.acceptedSource.SubmissionID || accepted.Source.AcceptedEventSeq == fixture.acceptedSource.AcceptedEventSeq || accepted.Source.SHA256 != fixture.acceptedSource.SHA256 {
		t.Fatal("reacceptance did not produce a new acceptance identity for the unchanged material:", err)
	}
	publishConsumptionProof(t, source, accepted.Source, &fixture.candidate, 1, nil)
	currentCandidate, err := source.svc.Queries.GetKnowledgeCandidate(source.ctx, fixture.candidate.ID)
	if err != nil || currentCandidate.ID != fixture.candidate.ID || currentCandidate.Version != fixture.candidate.Version || currentCandidate.ContentSha256 != fixture.candidate.ContentSha256 || currentCandidate.Content != fixture.candidate.Content || currentCandidate.State != "approved" || currentCandidate.ApprovalOrigin != "automation" {
		t.Fatal("proof replacement must retain the original approved automatic candidate/version/body/hash:", err)
	}
	if status, err := source.svc.KnowledgeUsageStatus(source.ctx, source.svc.Queries, currentCandidate); err != nil || status != "active" {
		t.Fatalf("proof2 must be genuinely active before the stale request is replayed: status=%s err=%v", status, err)
	}
	facts := knowledgeConsumerFixture(t, source, source.workspace)
	facts.ProtocolVersion, facts.ProjectID = 2, fixture.candidate.TargetProjectID
	current, err := source.svc.ResolveApprovedKnowledge(source.ctx, source.svc.Queries, facts)
	if err != nil || len(current.Manifest.Entries) != 1 || len(current.Contributions) != 1 || current.ManifestSHA256 == fixture.prepared.ManifestSHA256 {
		t.Fatal("current eligible proof2 resolution failed:", err)
	}
	entry := current.Manifest.Entries[0]
	originalEntry := fixture.prepared.Manifest.Entries[0]
	if entry.Validity == nil || entry.Validity.Revision != "2" || entry.Validity.AcceptedEventSeq != accepted.Source.AcceptedEventSeq || entry.Validity.SubmissionID != accepted.Source.SubmissionID || entry.Validity.ValidatedCloseEpoch == originalEntry.Validity.ValidatedCloseEpoch {
		t.Fatal("proof2 does not bind the new exact acceptance and close epoch")
	}
	originalEntry.Validity = entry.Validity
	if !reflect.DeepEqual(entry, originalEntry) {
		t.Fatal("reacceptance changed candidate identity instead of only replacing the validity proof")
	}
	knowledgeC3Log(t, "proof2_active_after_real_reacceptance", map[string]any{
		"original_source": fixture.acceptedSource, "new_accepted_source": accepted.Source, "original_manifest": fixture.prepared.Manifest,
		"current_manifest": current.Manifest, "current_manifest_sha256": current.ManifestSHA256, "usage_status": "active", "same_candidate_version_content_hash": true,
	})
	return current
}

func (fixture *knowledgeC3ReplayFixture) assertOriginalRetained(t *testing.T, stage string) {
	t.Helper()
	consumer := fixture.consumer
	retained, err := consumer.tasks.Queries.GetAgentTask(consumer.ctx, fixture.originalTask.ID)
	if err != nil {
		t.Fatal(err)
	}
	original := fixture.originalTask
	if retained.KnowledgeContextVersion != original.KnowledgeContextVersion || !bytes.Equal(retained.KnowledgeDelivery, original.KnowledgeDelivery) || retained.SessionID != original.SessionID || retained.ClaimGeneration != original.ClaimGeneration || retained.DispatchedAt != original.DispatchedAt || retained.Status != original.Status {
		t.Fatal("reacceptance/replay/fresh control changed the original stored request, manifest, receipt, session, claim or status")
	}
	if knowledgeC3Hash(t, fixture.prepareRequest) != fixture.prepareHash || fixture.authorizeHash != "" && knowledgeC3Hash(t, fixture.authorizeRequest) != fixture.authorizeHash {
		t.Fatal("the direct replay altered an original request/hash")
	}
	knowledgeC3Log(t, stage, map[string]any{
		"original_task_id": util.UUIDToString(original.ID), "retained_delivery_sha256": protocol.CollaborationKnowledgeHash(string(retained.KnowledgeDelivery)),
		"prepare_request_sha256": fixture.prepareHash, "authorize_request_sha256": fixture.authorizeHash,
		"request_manifest_receipt_session_claim_status_unchanged": true,
	})
}

func (fixture *knowledgeC3ReplayFixture) freshProofPositiveControl(t *testing.T, current KnowledgeResolution) {
	t.Helper()
	consumer := fixture.consumer
	consumer.nextTurn(t)
	descriptor := consumer.finalize(t, "")
	if consumer.task.ID == fixture.originalTask.ID || descriptor.Session.Generation == fixture.descriptor.Session.Generation || descriptor.Session.NativeSessionID != "" || descriptor.Session.ScopeID != fixture.descriptor.Session.ScopeID || descriptor.Session.RuntimeID != fixture.descriptor.Session.RuntimeID || descriptor.Session.AgentID != fixture.descriptor.Session.AgentID || descriptor.Session.ConfigurationID != fixture.descriptor.Session.ConfigurationID {
		t.Fatal("the proof2 control must be a genuine fresh execution with the same consumer configuration")
	}
	prepareRequest := consumer.prepareRequest(descriptor)
	prepared, err := consumer.tasks.PrepareTaskKnowledge(consumer.ctx, consumer.caller, consumer.task.ID, prepareRequest)
	if err != nil || prepared.ProtocolVersion != 2 || len(prepared.Contributions) != 1 || prepared.PrepareID == fixture.prepared.PrepareID || prepared.ManifestSHA256 != current.ManifestSHA256 || !sameTaskKnowledgeManifest(prepared.Manifest, current.Manifest) || prepared.Session != descriptor.Session {
		t.Fatal("genuine fresh execution did not prepare the current proof2:", err)
	}
	authorizeRequest := consumer.authorizeRequest(prepared, descriptor)
	authorized, err := consumer.tasks.AuthorizeTaskKnowledgeLaunch(consumer.ctx, consumer.caller, consumer.task.ID, authorizeRequest)
	want := protocol.TaskKnowledgeAuthorization{ProtocolVersion: 2, PrepareID: prepared.PrepareID, AttemptSequence: authorizeRequest.AttemptSequence, AttemptNonce: authorizeRequest.AttemptNonce,
		ManifestSHA256: prepared.ManifestSHA256, InvocationFingerprint: prepared.InvocationFingerprint, PromptSHA256: authorizeRequest.PromptSHA256, Session: descriptor.Session}
	if err != nil || authorized != want || authorizeRequest.RequestID == fixture.authorizeRequest.RequestID || authorizeRequest.AttemptNonce == fixture.authorizeRequest.AttemptNonce || prepareRequest.RequestID == fixture.prepareRequest.RequestID {
		t.Fatal("genuine fresh proof2 launch was not authorized with its own exact receipt:", err)
	}
	row, err := consumer.tasks.Queries.GetAgentTask(consumer.ctx, consumer.task.ID)
	if err != nil {
		t.Fatal(err)
	}
	delivery, err := decodeTaskKnowledge(row.KnowledgeContextVersion, row.KnowledgeDelivery)
	if err != nil {
		t.Fatal(err)
	}
	claim, err := taskKnowledgeClaimAt(delivery, row.ClaimGeneration)
	if err != nil || claim.Prepared == nil || claim.Prepared.RequestID != prepareRequest.RequestID || claim.Prepared.RequestHash != knowledgeC3Hash(t, prepareRequest) || len(claim.Attempts) != 1 || claim.Attempts[0].RequestID != authorizeRequest.RequestID || claim.Attempts[0].RequestHash != knowledgeC3Hash(t, authorizeRequest) || claim.Attempts[0].Authorization != authorized || claim.Attempts[0].Refused {
		t.Fatal("fresh proof2 positive control was not durably admitted through real prepare/authorize transactions")
	}
	knowledgeC3Log(t, "fresh_proof2_prepare_and_authorize_admitted", map[string]any{
		"task_id": util.UUIDToString(row.ID), "prepare_request": prepareRequest, "prepare_request_sha256": knowledgeC3Hash(t, prepareRequest), "prepare_response": prepared,
		"authorize_request": authorizeRequest, "authorize_request_sha256": knowledgeC3Hash(t, authorizeRequest), "authorization_receipt": authorized,
		"retained_delivery_sha256": protocol.CollaborationKnowledgeHash(string(row.KnowledgeDelivery)), "retained_attempt_count": 1,
		"same_runtime_agent_scope_configuration": true, "fresh_session_generation": true, "proof_revision": "2",
	})
	fixture.assertOriginalRetained(t, "original_retained_after_fresh_positive_control")
}

func TestKnowledgeC3ReacceptanceOriginalPrepareReplay(t *testing.T) {
	fixture := newKnowledgeC3ReplayFixture(t, false)
	current := fixture.replaceProofThroughReacceptance(t)
	fixture.assertOriginalRetained(t, "original_retained_before_stale_replay")
	consumer := fixture.consumer
	replayed, err := consumer.tasks.PrepareTaskKnowledge(consumer.ctx, consumer.caller, fixture.originalTask.ID, fixture.prepareRequest)
	var refusal *CollaborationError
	if !errors.As(err, &refusal) || refusal.Status != 409 || refusal.Code != "knowledge_context_changed" || !reflect.DeepEqual(replayed, protocol.TaskKnowledgePrepareResponse{}) {
		t.Fatalf("the ORIGINAL proof1 prepare request must be denied after active proof2 replaces it: %v", err)
	}
	knowledgeC3Log(t, "original_prepare_direct_replay_denied", map[string]any{
		"status": refusal.Status, "code": refusal.Code, "request_id": fixture.prepareRequest.RequestID, "request_sha256": knowledgeC3Hash(t, fixture.prepareRequest),
		"original_prepare_id": fixture.prepared.PrepareID, "original_manifest_sha256": fixture.prepared.ManifestSHA256, "response_is_zero": true,
	})
	fixture.assertOriginalRetained(t, "original_retained_after_stale_replay")
	fixture.freshProofPositiveControl(t, current)
}

func TestKnowledgeC3ReacceptanceOriginalAuthorizeReplay(t *testing.T) {
	fixture := newKnowledgeC3ReplayFixture(t, true)
	current := fixture.replaceProofThroughReacceptance(t)
	fixture.assertOriginalRetained(t, "original_retained_before_stale_replay")
	consumer := fixture.consumer
	replayed, err := consumer.tasks.AuthorizeTaskKnowledgeLaunch(consumer.ctx, consumer.caller, fixture.originalTask.ID, fixture.authorizeRequest)
	var refusal *CollaborationError
	if !errors.As(err, &refusal) || refusal.Status != 409 || refusal.Code != "knowledge_context_changed" || replayed != (protocol.TaskKnowledgeAuthorization{}) {
		t.Fatalf("the ORIGINAL admitted proof1 authorize request must be denied instead of replaying its old receipt after proof2 replaces it: %v", err)
	}
	knowledgeC3Log(t, "original_authorize_direct_replay_denied", map[string]any{
		"status": refusal.Status, "code": refusal.Code, "request_id": fixture.authorizeRequest.RequestID, "request_sha256": knowledgeC3Hash(t, fixture.authorizeRequest),
		"original_authorization_receipt": fixture.authorized, "response_is_zero": true,
	})
	fixture.assertOriginalRetained(t, "original_retained_after_stale_replay")
	fixture.freshProofPositiveControl(t, current)
}

