    generated = []
    paths = sorted(path for group in ["server", "scripts"] for path in (IMMUTABLE / group).rglob("*") if path.is_file())
    for original in paths:
        relative = str(original.relative_to(IMMUTABLE))
        staged = SOURCE / relative
        if original.is_symlink() or staged.is_symlink():
            raise RuntimeError("source copy must have no outward symlink")
        content = original.read_bytes()
        sha = hashlib.sha256(content).hexdigest()
