        files[relative] = {"sha256": sha, "mode": mode, "size_bytes": len(content), "kind": kind,
                           "immutable_path": str(original), "staged_path": str(staged), "build_source_snapshot_member_and_equal": snapshot_equal}
        fingerprints["all_server_scripts"].update(relative.encode() + b"\0" + content)
        if kind in {"production_go", "sql", "module_files"}:
            fingerprints["production_go_sql_mod"].update(relative.encode() + b"\0" + content)
        if kind == "existing_go_tests":
            fingerprints["existing_go_tests"].update(relative.encode() + b"\0" + content)
    extras = sorted(str(path.relative_to(SOURCE)) for group in ["server", "scripts"] for path in (SOURCE / group).rglob("*") if path.is_file() and str(path.relative_to(SOURCE)) not in files)
    if extras != [str(ADDED_TEST.relative_to(SOURCE))]:
