    report = {"schema": "multica.c3.staged-input-manifest.v1", "source_id": SOURCE_ID, "immutable_source": str(IMMUTABLE), "private_source": str(SOURCE),
              "binding_build_json": str(BUILD / "build.json"), "binding_build_sha256": digest(BUILD / "build.json"),
              "source_environment_json": str(BUILD / "environment.json"), "source_environment_sha256": digest(BUILD / "environment.json"),
              "copied_scope": ["complete server/", "complete scripts/", "AGENTS.md", "CLAUDE.md"], "files": files, "counts": counts,
