def json_stream(text):
    decoder = json.JSONDecoder()
    offset = 0
    records = []
    while offset < len(text):
        while offset < len(text) and text[offset].isspace():
            offset += 1
        if offset == len(text):
            break
        value, offset = decoder.raw_decode(text, offset)
        records.append(value)
    return records


def escaped_module(value):
    return "".join("!" + char.lower() if char.isupper() else char for char in value)


def copy_cached_modules(resume=False):
    retained_env = json.loads((BUILD / "environment.json").read_text())
    existing = Path(retained_env["GOMODCACHE"]).resolve(strict=True)
    target = PRIVATE / "gomodcache"
    if resume:
        if not target.is_dir():
            raise RuntimeError("retained private metadata cache is missing")
    else:
        target.mkdir(mode=0o700)
    metadata_count = 0
    for path in sorted((existing / "cache/download").rglob("*")):
        if path.is_file() and (path.suffix in {".mod", ".info", ".ziphash"} or path.name == "list") and "sumdb" not in path.relative_to(existing).parts:
            destination = target / path.relative_to(existing)
            if not resume:
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(path, destination)
            metadata_count += 1
    if resume:
        record = next(record for record in STATE["commands"] if record["label"] == "module-list" and record["exit"] == 0)
    else:
        record = required_command("module-list", [GO, "-C", SOURCE / "server", "list", "-m", "-json", "all"], isolated_env())
    modules = json_stream(Path(record["raw_log"]).read_text())
    copied = []
    unextracted_metadata = []
    for module in modules:
        if module.get("Main"):
            continue
        if module.get("Replace") or not module.get("Version"):
            raise RuntimeError("unexpected module replacement or unpinned dependency")
        relative = escaped_module(module["Path"]) + "@" + escaped_module(module["Version"])
        original = existing / relative
        if not original.is_dir():
            if not resume:
                raise RuntimeError("a pinned module is not already available in the existing cache")
            unextracted_metadata.append({"path": module["Path"], "version": module["Version"], "reason": "metadata-only graph member; actual selected compilation graph must prove no missing source before execution"})
            continue
        destination = target / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        if not destination.exists():
            shutil.copytree(original, destination, copy_function=shutil.copy2, symlinks=True)
        fingerprint = hashlib.sha256()
        count = 0
        total = 0
        for path in sorted(original.rglob("*")):
            if path.is_symlink():
                raise RuntimeError("unexpected symlink in cached module")
            if path.is_file():
                content = path.read_bytes()
                item = str(path.relative_to(original))
                if (destination / item).read_bytes() != content:
                    raise RuntimeError("private dependency cache copy differs")
                fingerprint.update(item.encode() + b"\0" + content)
                count += 1
                total += len(content)
        copied.append({"path": module["Path"], "version": module["Version"], "existing_cache_path": str(original), "private_path": str(destination),
                       "exact_file_count": count, "size_bytes": total, "byte_fingerprint": fingerprint.hexdigest()})
    report = {"existing_cache_read_only_source": str(existing), "private_module_cache": str(target), "metadata_files_copied": metadata_count,
              "new_dependency_installation": False, "network_module_fetching": False, "modules": copied, "unextracted_metadata_only_members": unextracted_metadata,
              "resumed_existing_module_inventory_without_reexecuting_command": resume}
    save(PRIVATE / "module-cache-copy.json", report, exclusive=True)
    STATE["private_dependency_cache"] = {"path": str(PRIVATE / "module-cache-copy.json"), "sha256": digest(PRIVATE / "module-cache-copy.json"), "module_count": len(copied),
                                         "new_dependencies": False, "GOPROXY": "off", "GOSUMDB": "off"}
    save(STATE_PATH, STATE)


