    manifest = json.loads((PRIVATE / "source-copy-manifest.json").read_text())
    mismatches = []
    for relative, expected in manifest["files"].items():
        for root in [IMMUTABLE, SOURCE]:
            path = root / relative
            if not path.is_file() or path.is_symlink() or digest(path) != expected["sha256"] or stat.S_IMODE(path.stat().st_mode) != expected["mode"]:
                mismatches.append({"root": str(root), "path": relative})
