    active_input = STATE.get("active_added_test_input", {"version": 1, "sha256": manifest["added_test_sha256"]})
    if extras != [str(ADDED_TEST.relative_to(SOURCE))] or digest(ADDED_TEST) != active_input["sha256"]:
