def endpoint():
    path = BUILD / "environment.json"
    if path.stat().st_uid != os.getuid() or stat.S_IMODE(path.stat().st_mode) != 0o600 or digest(path) != STATE["source_environment_sha256"]:
        raise RuntimeError("retained endpoint file ownership or identity differs")
    value = json.loads(path.read_text())["DATABASE_URL"]
    if not isinstance(value, str) or "$" in value or any(ord(char) < 32 for char in value):
        raise RuntimeError("endpoint must be literal private configuration data")
    parsed = urllib.parse.urlparse(value)
    if parsed.scheme not in {"postgres", "postgresql"} or parsed.hostname not in {"127.0.0.1", "localhost", "::1"} or parsed.fragment:
        raise RuntimeError("only the retained loopback endpoint is permitted")
    return parsed


def sql(label, statement, database="postgres"):
    if any(record["label"] == label for record in STATE["database_operations"]):
        raise RuntimeError("a database operation label may not be reused")
    if database != "postgres" and database != STATE.get("database", {}).get("name"):
        raise RuntimeError("only maintenance reads or this unique owned database are permitted")
    parsed = endpoint()
    child_env = isolated_env()
    child_env.update(PGHOST=parsed.hostname, PGPORT=str(parsed.port or 5432), PGUSER=urllib.parse.unquote(parsed.username or ""),
                     PGPASSWORD=urllib.parse.unquote(parsed.password or ""), PGDATABASE=database, PGCONNECT_TIMEOUT="5", PGAPPNAME="c3-direct-replay-owned")
    for key, value in urllib.parse.parse_qsl(parsed.query):
        if key == "sslmode":
            child_env["PGSSLMODE"] = value
    log = PRIVATE / "logs" / (label + ".sql.log")
    record = {"label": label, "argv": [str(PSQL), "-X", "-A", "-t", "-v", "ON_ERROR_STOP=1", "-c", statement],
              "database": database, "started_at": utc(), "raw_log": str(log), "role": "create_unique_owned_database" if statement.startswith("CREATE DATABASE") else "read_only"}
    STATE["database_operations"].append(record)
    save(STATE_PATH, STATE)
    result = subprocess.run(record["argv"], cwd=PRIVATE, env=child_env, capture_output=True, text=True, timeout=30)
    with log.open("x") as output:
        output.write(result.stdout)
        output.write(result.stderr)
    log.chmod(0o600)
    record.update(exit=result.returncode, finished_at=utc(), raw_log_sha256=digest(log))
    save(STATE_PATH, STATE)
    if result.returncode:
        STATE["original_failures"].append({"label": label, "exit": result.returncode, "raw_log": str(log)})
        save(STATE_PATH, STATE)
        raise RuntimeError("owned database operation failed; private raw diagnostics retained")
    return result.stdout.strip()


def ledger(label):
    name = STATE["database"]["name"]
    versions = json.loads(sql(label, "SELECT COALESCE(json_agg(version ORDER BY version),'[]'::json) FROM schema_migrations", name))
    expected = sorted(path.name.removesuffix(".up.sql") for path in (SOURCE / "server/migrations").glob("*.up.sql"))
    if versions != expected:
        raise RuntimeError("owned database migration ledger is not the exact complete immutable migration set")
    return {"count": len(versions), "maximum": max(versions), "versions": versions, "versions_sha256": hashlib.sha256(json.dumps(versions, separators=(",", ":")).encode()).hexdigest(),
            "exact_full_immutable_set": True, "conditionally_skipped_sql_still_recorded_by_original_runner": True}


def connections(label):
    return int(sql(label, "SELECT count(*) FROM pg_stat_activity WHERE datname='" + STATE["database"]["name"] + "'"))


