    STATE["owned_environment"] = {"path": str(PRIVATE / "environment.json"), "sha256": digest(PRIVATE / "environment.json"), "mode": "0600",
                                  "credential_values_printed": False, "inherited_source_environment_keys": ["DATABASE_URL endpoint components only; database replaced"],
                                  "redis_present": False, "real_model_configuration_present": False, "api_pool_overrides_present": False}
    migration_files = {str(path.relative_to(SOURCE)): {"sha256": digest(path), "mode": stat.S_IMODE(path.stat().st_mode)} for path in sorted((SOURCE / "server/migrations").glob("*.up.sql"))}
    save(PRIVATE / "migration-input-map.json", {"source_id": SOURCE_ID, "up_migration_files": migration_files}, exclusive=True)
    STATE["database"]["migration_input_map"] = {"path": str(PRIVATE / "migration-input-map.json"), "sha256": digest(PRIVATE / "migration-input-map.json"), "up_file_count": len(migration_files)}
