def parse_test_output(path):
    inventory = {key: [] for key in ["run", "pass", "fail", "skip"]}
    package_events, output_by_test, non_json_lines = [], {}, []
    for line in Path(path).read_text().splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            non_json_lines.append(line)
            continue
        name = event.get("Test", "")
        if name and event.get("Action") in inventory:
            inventory[event["Action"]].append(name)
        if not name and event.get("Action") in {"start", "pass", "fail", "skip"}:
            package_events.append(event)
        if event.get("Action") == "output":
            output_by_test.setdefault(name, []).append(event.get("Output", ""))
    traces = []
    for name in inventory["run"]:
        # Go JSON may split one long t.Log line into several Output events.
        # Reassemble per Test before extracting the exact structured record.
        for line in "".join(output_by_test.get(name, [])).splitlines():
            if "C3_EVIDENCE " in line:
                trace = json.loads(line.split("C3_EVIDENCE ", 1)[1])
                if trace.get("test") != name:
                    raise RuntimeError("structured trace test identity differs from its raw event stream")
                traces.append(trace)
    return inventory, package_events, traces, non_json_lines


